create function app.seed_foundation() returns void language plpgsql security definer set search_path='' as $$
declare o uuid:='10000000-0000-4000-8000-000000000001'; s uuid:='10000000-0000-4000-8000-000000000002'; role_name text; m uuid; cls text; lev text; roles_json jsonb; pair record;
all_roles text[]:=array['ecm_provider','cf_care_manager','sud_counselor','clinical_trainee','medical_assistant','peer_specialist','community_health_worker','therapist','physician','pmhnp','nurse_rn','lvn','billing','clinical_coordinator','intake_coordinator','credentialing_coordinator','billing_coordinator','sys_admin'];
all_classes text[]:=array['account_support','demographics','screeners_mh','screeners_sud','psych_eval','care_plan','therapy_notes','meds_erx','telehealth_room','sdoh','self_help','safety_plan','sud_treatment','psychotherapy_notes','case_notes','peer_notes','chw_notes','documents','billing','consent_ledger','problems','allergies','alerts','eligibility','care_coordination','custody_tracking','pre_release','controlled_substance_custody','population_health','crisis_queue','patient_messaging','provider_requests','community_inquiries','worklist','note_templates','catalog_governance','platform_administration','scheduling_rules','group_sessions','group_notes','staff_supervision','assisted_signup','content_authoring','clinical_text_governance'];
g jsonb:='{"demographics":{"write":["ecm_provider","clinical_coordinator","sys_admin"],"read":["cf_care_manager","sud_counselor","clinical_trainee","medical_assistant","peer_specialist","community_health_worker","therapist","physician","pmhnp","nurse_rn","lvn","billing","billing_coordinator"]},"screeners_mh":{"write":["ecm_provider"],"read":["sud_counselor","clinical_trainee","peer_specialist","therapist","physician","pmhnp","nurse_rn","lvn"]},"screeners_sud":{"consent_gated":["ecm_provider","clinical_trainee","peer_specialist"],"read":["sud_counselor","therapist","physician","pmhnp","nurse_rn","lvn"]},"psych_eval":{"read":["ecm_provider","sud_counselor","clinical_trainee","peer_specialist","therapist"],"write":["physician","pmhnp"]},"care_plan":{"write":["ecm_provider","cf_care_manager","sud_counselor","clinical_trainee","therapist","physician","pmhnp"],"read":["peer_specialist","nurse_rn","lvn","clinical_coordinator","sys_admin"]},"therapy_notes":{"summary":["ecm_provider"],"read":["sud_counselor","physician","pmhnp"],"write":["clinical_trainee","therapist"]},"meds_erx":{"read":["ecm_provider","clinical_trainee","medical_assistant","therapist","nurse_rn","lvn"],"write":["physician","pmhnp"]},"telehealth_room":{"read":["ecm_provider","clinical_trainee"],"write":["sud_counselor","therapist","physician","pmhnp"]},"sdoh":{"write":["ecm_provider","cf_care_manager","sud_counselor","peer_specialist","community_health_worker","therapist","physician","pmhnp"]},"self_help":{"write":["ecm_provider","sud_counselor","peer_specialist","therapist","physician","pmhnp"]},"safety_plan":{"write":["ecm_provider","sud_counselor","therapist","physician","pmhnp","clinical_coordinator"],"read":["cf_care_manager","clinical_trainee","medical_assistant","peer_specialist","community_health_worker","sys_admin"]},"sud_treatment":{"consent_gated":["ecm_provider","clinical_trainee","peer_specialist","therapist","billing"],"write":["sud_counselor","physician","pmhnp"],"read":["nurse_rn","lvn"]},"case_notes":{"write":["ecm_provider","sud_counselor","clinical_trainee"],"read":["cf_care_manager","peer_specialist","community_health_worker","therapist","physician","pmhnp"]},"peer_notes":{"read":["ecm_provider","therapist","physician","pmhnp"],"write":["peer_specialist"]},"chw_notes":{"read":["ecm_provider","therapist","physician","pmhnp","clinical_coordinator"],"write":["community_health_worker"]},"documents":{"write":["ecm_provider"],"read":["cf_care_manager","sud_counselor","medical_assistant","therapist","physician","pmhnp","nurse_rn","lvn"]},"consent_ledger":{"write":["ecm_provider","sud_counselor","sys_admin"],"read":["cf_care_manager","peer_specialist","therapist","physician","pmhnp","nurse_rn","billing","clinical_coordinator","billing_coordinator"]},"problems":{"read":["ecm_provider","sud_counselor","clinical_trainee","medical_assistant","peer_specialist","nurse_rn","lvn","billing","clinical_coordinator","billing_coordinator"],"write":["therapist","physician","pmhnp"]},"allergies":{"read":["ecm_provider","sud_counselor","clinical_trainee","medical_assistant","peer_specialist","lvn","clinical_coordinator"],"write":["therapist","physician","pmhnp","nurse_rn"]},"alerts":{"write":["ecm_provider","therapist","physician","pmhnp"],"read":["sud_counselor","clinical_trainee","medical_assistant","peer_specialist","nurse_rn","lvn","clinical_coordinator"]},"eligibility":{"write":["ecm_provider","billing","billing_coordinator"],"read":["cf_care_manager","sud_counselor","therapist","physician","pmhnp","clinical_coordinator"]},"care_coordination":{"write":["ecm_provider","cf_care_manager","sud_counselor","community_health_worker","therapist","physician","pmhnp"],"read":["clinical_trainee","peer_specialist","clinical_coordinator"]},"custody_tracking":{"write":["ecm_provider","cf_care_manager","clinical_coordinator"],"read":["peer_specialist","therapist","physician","pmhnp","sys_admin"]},"pre_release":{"write":["ecm_provider","cf_care_manager","physician","pmhnp"],"read":["sud_counselor","therapist","clinical_coordinator","sys_admin"]},"controlled_substance_custody":{"read":["ecm_provider","clinical_trainee","medical_assistant","therapist","nurse_rn","lvn"],"write":["physician","pmhnp"]},"population_health":{"read":["ecm_provider","therapist","physician","pmhnp"],"write":["clinical_coordinator","sys_admin"]},"crisis_queue":{"read":["ecm_provider","cf_care_manager","therapist","physician","pmhnp"],"write":["clinical_coordinator","sys_admin"]},"patient_messaging":{"write":["ecm_provider","sud_counselor","peer_specialist","therapist","physician","pmhnp"],"read":["cf_care_manager","clinical_trainee","clinical_coordinator","sys_admin"]},"provider_requests":{"write":["ecm_provider","sud_counselor","therapist","physician","pmhnp","nurse_rn"],"read":["clinical_trainee","medical_assistant","peer_specialist","clinical_coordinator","sys_admin"]},"community_inquiries":{"write":["ecm_provider","sud_counselor","peer_specialist","community_health_worker","therapist","physician","pmhnp","clinical_coordinator"],"read":["clinical_trainee","medical_assistant","sys_admin"]},"worklist":{"write":["ecm_provider","cf_care_manager","sud_counselor","community_health_worker","therapist","physician","pmhnp"],"read":["clinical_trainee","medical_assistant","peer_specialist","nurse_rn","lvn","clinical_coordinator","sys_admin"]},"note_templates":{"read":["ecm_provider","sud_counselor","clinical_trainee","peer_specialist","therapist","physician","pmhnp"],"write":["clinical_coordinator","sys_admin"]},"scheduling_rules":{"read":["ecm_provider","therapist","physician","pmhnp"],"write":["clinical_coordinator","sys_admin"]},"group_sessions":{"write":["ecm_provider","sud_counselor","therapist","physician","pmhnp","clinical_coordinator","sys_admin"],"read":["clinical_trainee","peer_specialist","billing","billing_coordinator"]},"group_notes":{"consent_gated":["ecm_provider","clinical_trainee","peer_specialist","billing","clinical_coordinator"],"write":["sud_counselor","therapist","physician","pmhnp"]},"assisted_signup":{"write":["ecm_provider","cf_care_manager","peer_specialist","sys_admin"]},"content_authoring":{"write":["ecm_provider","cf_care_manager","sud_counselor","clinical_trainee","peer_specialist","community_health_worker","therapist","physician","pmhnp","clinical_coordinator","sys_admin"],"read":["medical_assistant"]},"clinical_text_governance":{"read":["ecm_provider","clinical_trainee","medical_assistant","therapist"],"write":["physician","pmhnp","clinical_coordinator","sys_admin"]},"staff_supervision":{"read":["clinical_trainee","medical_assistant","community_health_worker","therapist","physician","pmhnp"],"write":["clinical_coordinator","credentialing_coordinator","sys_admin"]},"billing":{"write":["billing","billing_coordinator"],"read":["sys_admin"]},"catalog_governance":{"write":["clinical_coordinator","sys_admin"]},"platform_administration":{"read":["clinical_coordinator"],"write":["sys_admin"]},"account_support":{"write":["sys_admin"]}}';
begin
insert into public.orgs(id,org_id,code,name) values(o,o,'fictional_beta','Fictional Beta Organization') on conflict do nothing;
insert into public.sites(id,org_id,code,name) values(s,o,'fictional_outpatient','Fictional Outpatient Site') on conflict do nothing;
insert into public.locations(org_id,site_id,code,name) values(o,s,'fictional_clinic','Fictional Clinic') on conflict do nothing;
insert into public.programs(org_id,site_id,code,name) values(o,s,'outpatient_mh','Fictional Outpatient Mental Health'),(o,s,'outpatient_sud','Fictional Outpatient Recovery') on conflict do nothing;
insert into public.county_programs(org_id,program_id,county_code) select o,id,'fictional_county' from public.programs where org_id=o and not exists(select 1 from public.county_programs where org_id=o);
foreach role_name in array all_roles loop
insert into public.staff_members(org_id,source_key,name) values(o,'beta_'||role_name,'Fictional Beta '||replace(role_name,'_',' ')) on conflict(org_id,source_key) do nothing;
select id into m from public.staff_members where org_id=o and source_key='beta_'||role_name;
insert into public.staff_role_assignments(org_id,staff_member_id,role,is_primary) values(o,m,role_name,true) on conflict do nothing;
if role_name='sys_admin' then insert into public.staff_role_assignments(org_id,staff_member_id,role,is_primary) values(o,m,'intake_coordinator',false) on conflict do nothing; end if;
foreach cls in array all_classes loop insert into app.record_class_grants(org_id,role,record_class,level) values(o,role_name,cls,'none') on conflict(role,record_class) do nothing; end loop;
end loop;
for pair in select key,value from jsonb_each(g) loop cls:=pair.key; for lev,roles_json in select key,value from jsonb_each(pair.value) loop update app.record_class_grants set level=lev where record_class=cls and role in (select jsonb_array_elements_text(roles_json)); end loop; end loop;
foreach cls in array array['persist_accounts','persist_staff_roles','persist_feature_flags','persist_audit','persist_consent','persist_patients_core','beta_foundation'] loop insert into public.feature_flags(org_id,flag_id) values(o,cls) on conflict do nothing; end loop;
foreach cls in array array['hie_simulated','voice_intake','adel_drafts','placeholder_lab','cures_placeholder','eligibility_simulated','erx_simulated','telehealth_simulated','caloms_export_simulated','notifications_simulated','payments_simulated','scribe_simulated','llm_simulated','calendar_sync_simulated','consent_upload_simulated'] loop insert into public.feature_flags(org_id,flag_id,enabled,simulated,mode) values(o,cls,true,true,'on') on conflict do nothing; end loop;
if not exists(select 1 from public.audit_events where org_id=o and action_code='foundation.seeded') then insert into public.audit_events(org_id,actor_role,action_code,outcome,simulated,registry_version,metadata) values(o,'system_migration','foundation.seeded','simulated',true,'roles-oct27-44x18','{"seed_code":"fictional_foundation_v1"}'); end if;
end $$;
revoke all on function app.seed_foundation() from public,anon,authenticated; grant execute on function app.seed_foundation() to service_role;
select app.seed_foundation();
create function app.role_assignment_guard() returns trigger language plpgsql set search_path='' as $$ begin if not exists(select 1 from app.record_class_grants where role=new.role) then raise exception 'unknown_staff_role'; end if; return new; end $$;
create trigger held_role_validation before insert or update on public.staff_role_assignments for each row execute function app.role_assignment_guard();
create function app.feature_guard() returns trigger language plpgsql set search_path='' as $$ begin if new.simulated and new.mode='live' then raise exception 'simulated_cannot_go_live'; end if; if tg_op='UPDATE' and new.simulated is distinct from old.simulated then raise exception 'feature_definition_is_code'; end if; return new; end $$;
create trigger feature_definition_guard before insert or update on public.feature_flags for each row execute function app.feature_guard();
create function public.foundation_command(p_user uuid,p_command text,p_value text) returns jsonb language plpgsql security definer set search_path='' as $$ declare result jsonb; begin
if not exists(select 1 from public.accounts where auth_user_id=p_user and active and synthetic) then raise exception 'beta_account_required'; end if;
perform set_config('request.jwt.claim.sub',p_user::text,true);
perform set_config('request.jwt.claims',jsonb_build_object('sub',p_user,'role','authenticated')::text,true);
if p_command='attest' then result:=jsonb_build_object('id',app.attest_beta(p_value));
elsif p_command='set_role' then result:=jsonb_build_object('role',app.set_acting_role(p_value));
else raise exception 'unknown_foundation_command'; end if;
return result;
end $$;
revoke all on function public.foundation_command(uuid,text,text) from public,anon,authenticated; grant execute on function public.foundation_command(uuid,text,text) to service_role;
revoke all on function app.role_assignment_guard(),app.feature_guard() from public,anon,authenticated; grant execute on function app.role_assignment_guard(),app.feature_guard() to service_role;
notify pgrst,'reload schema';